-- Egel
WITH a AS (
  INSERT INTO public.academies (diersoort_naam, diersoort_naam_fr, diersoort_naam_en, slug, badge_icon, vragen_per_test, slaag_grens, beschrijving, beschrijving_fr, beschrijving_en, categorie, prioriteit)
  VALUES ('Egel','Hérisson','Hedgehog','egel','egel',15,12,'Leer hoe je egels in de stad beschermt: veilige voeding, een egelvriendelijke tuin, gevaren vermijden en de winterslaap respecteren.','Découvrez comment protéger les hérissons en ville : alimentation sûre, jardin accueillant, dangers à éviter et respect de l''hibernation.','Learn how to protect hedgehogs in the city: safe food, a hedgehog-friendly garden, avoiding dangers and respecting hibernation.','stadsnatuur',50)
  RETURNING id
)
INSERT INTO public.academy_vragen (academy_id, module, vraag_type, vraag_tekst, vraag_tekst_fr, vraag_tekst_en, opties, opties_fr, opties_en, correcte_optie_index, wist_je_dat, wist_je_dat_fr, wist_je_dat_en)
SELECT a.id, v.module, v.vraag_type, v.nl, v.fr, v.en, v.onl, v.ofr, v.oen, v.ci, v.wnl, v.wfr, v.wen
FROM a, (VALUES
(1,'tekst','Wat mag je een egel het beste geven als bijvoeder?','Que vaut-il mieux donner à manger à un hérisson en complément ?','What is the best supplemental food to give a hedgehog?',
 '["Speciaal egelvoer of nat kattenvoer","Melk in een schaaltje","Brood met melk","Chocolade"]'::jsonb,
 '["De la nourriture spéciale pour hérissons ou de la pâtée pour chats","Du lait dans une coupelle","Du pain trempé dans du lait","Du chocolat"]'::jsonb,
 '["Special hedgehog food or wet cat food","Milk in a bowl","Bread soaked in milk","Chocolate"]'::jsonb,
 0,'Egels zijn lactose-intolerant: melk veroorzaakt diarree en kan hen ernstig ziek maken.','Les hérissons sont intolérants au lactose : le lait provoque des diarrhées et peut les rendre gravement malades.','Hedgehogs are lactose intolerant: milk causes diarrhoea and can make them seriously ill.'),
(1,'tekst','Waarom is brood geen goed voedsel voor egels?','Pourquoi le pain n''est-il pas une bonne nourriture pour les hérissons ?','Why is bread not good food for hedgehogs?',
 '["Het zwelt op in de maag en heeft weinig voedingswaarde","Egels houden er niet van","Het is te duur","Brood is juist heel gezond voor egels"]'::jsonb,
 '["Il gonfle dans l''estomac et a peu de valeur nutritive","Les hérissons n''aiment pas ça","C''est trop cher","Le pain est en fait très sain pour les hérissons"]'::jsonb,
 '["It swells in the stomach and has little nutritional value","Hedgehogs dislike it","It is too expensive","Bread is actually very healthy for hedgehogs"]'::jsonb,
 0,'Brood kan opzwellen in de maag van een egel en veroorzaakt spijsverteringsproblemen.','Le pain peut gonfler dans l''estomac du hérisson et provoquer des problèmes digestifs.','Bread can swell in a hedgehog''s stomach and cause digestive problems.'),
(1,'tekst','Wat kan je best in de tuin laten liggen om egels te helpen?','Que vaut-il mieux laisser dans le jardin pour aider les hérissons ?','What is best left in the garden to help hedgehogs?',
 '["Een hoop bladeren of takken als schuilplaats","Enkel gemaaid gazon zonder begroeiing","Plastic afval","Felle buitenverlichting de hele nacht"]'::jsonb,
 '["Un tas de feuilles ou de branches comme abri","Uniquement une pelouse tondue sans végétation","Des déchets plastiques","Un éclairage extérieur vif toute la nuit"]'::jsonb,
 '["A pile of leaves or branches as shelter","Only mown lawn with no vegetation","Plastic waste","Bright outdoor lighting all night"]'::jsonb,
 0,'Een takkenhoop of bladerhoop biedt egels een veilige schuilplaats en nestgelegenheid.','Un tas de branches ou de feuilles offre au hérisson un abri sûr et un lieu de nidification.','A pile of branches or leaves gives hedgehogs a safe shelter and nesting spot.'),
(1,'tekst','Hoe maak je een tuinafsluiting egelvriendelijk?','Comment rendre une clôture de jardin adaptée aux hérissons ?','How do you make a garden fence hedgehog-friendly?',
 '["Laat een opening van ongeveer 13 cm onderaan de afsluiting","Sluit de tuin volledig hermetisch af","Plaats prikkeldraad rond de tuin","Egels kunnen prima over muren klimmen"]'::jsonb,
 '["Laisser une ouverture d''environ 13 cm en bas de la clôture","Fermer complètement et hermétiquement le jardin","Installer du fil barbelé autour du jardin","Les hérissons grimpent très bien les murs"]'::jsonb,
 '["Leave a gap of about 13 cm at the bottom of the fence","Seal the garden completely","Put barbed wire around the garden","Hedgehogs climb walls easily"]'::jsonb,
 0,'Egels leggen elke nacht kilometers af op zoek naar voedsel en partners, kleine doorgangen zijn essentieel.','Chaque nuit, les hérissons parcourent des kilomètres à la recherche de nourriture et de partenaires, de petits passages sont essentiels.','Hedgehogs travel kilometres each night searching for food and mates, small passages are essential.'),
(1,'tekst','Wat is een egelvriendelijk alternatief voor een vijver zonder oever?','Quelle est une alternative adaptée aux hérissons pour un bassin sans berge ?','What is a hedgehog-friendly alternative for a pond without a shore?',
 '["Een flauwe helling of uitstapplank in het water","Gladde, steile wanden","Geen water in de tuin toelaten","Een net strak over het water spannen"]'::jsonb,
 '["Une pente douce ou une planche de sortie dans l''eau","Des parois lisses et abruptes","Ne jamais autoriser d''eau dans le jardin","Tendre un filet bien tendu sur l''eau"]'::jsonb,
 '["A gentle slope or exit ramp in the water","Smooth, steep walls","Never allow water in the garden","A tightly stretched net over the water"]'::jsonb,
 0,'Egels kunnen zwemmen maar verdrinken vaak in vijvers zonder uitstapmogelijkheid.','Les hérissons savent nager mais se noient souvent dans des bassins sans moyen de sortir.','Hedgehogs can swim but often drown in ponds with no way to climb out.'),
(2,'tekst','Welk gevaar vormen maairobots voor egels?','Quel danger représentent les robots tondeuses pour les hérissons ?','What danger do robotic lawnmowers pose to hedgehogs?',
 '["Ze kunnen egels ernstig verwonden omdat egels zich oprollen in plaats van vluchten","Ze zijn totaal onschadelijk voor egels","Egels zijn bang van het geluid en blijven altijd weg","Maairobots werken enkel overdag"]'::jsonb,
 '["Ils peuvent gravement blesser les hérissons car ceux-ci se roulent en boule au lieu de fuir","Ils sont totalement inoffensifs pour les hérissons","Les hérissons ont peur du bruit et restent toujours à l''écart","Les robots tondeuses ne fonctionnent que le jour"]'::jsonb,
 '["They can seriously injure hedgehogs because hedgehogs curl up instead of fleeing","They are completely harmless to hedgehogs","Hedgehogs fear the noise and always stay away","Robotic mowers only run during the day"]'::jsonb,
 0,'Egels rollen zich op bij gevaar in plaats van te vluchten, waardoor maairobots hen ernstig kunnen verwonden ''s nachts.','Les hérissons se mettent en boule face au danger au lieu de fuir, ce qui les expose gravement aux robots tondeuses la nuit.','Hedgehogs curl into a ball when threatened instead of fleeing, which makes them vulnerable to mowers at night.'),
(2,'tekst','Waarom zijn losse tuinnetten gevaarlijk voor egels?','Pourquoi les filets de jardin non fixés sont-ils dangereux pour les hérissons ?','Why are loose garden nets dangerous for hedgehogs?',
 '["Egels raken erin verstrikt en kunnen niet meer loskomen","Egels eten de netten op","Netten trekken juist egels aan om te spelen","Er is geen enkel gevaar"]'::jsonb,
 '["Les hérissons s''y emmêlent et ne peuvent plus se libérer","Les hérissons mangent les filets","Les filets attirent les hérissons pour jouer","Il n''y a aucun danger"]'::jsonb,
 '["Hedgehogs get entangled in them and cannot free themselves","Hedgehogs eat the nets","Nets actually attract hedgehogs to play","There is no danger at all"]'::jsonb,
 0,'Losse netten zoals fruitnetten kunnen egels verstrikken, wat leiden kan tot verwondingen of verhongering.','Les filets non fixés, comme les filets à fruits, peuvent emmêler les hérissons, causant blessures ou famine.','Loose nets like fruit netting can entangle hedgehogs, leading to injury or starvation.'),
(2,'tekst','Waarom controleer je een composthoop voor je erin harkt?','Pourquoi faut-il vérifier un tas de compost avant d''y planter une fourche ?','Why should you check a compost heap before forking into it?',
 '["Egels gebruiken composthopen vaak als schuilplaats of nest","Compost is altijd veilig zonder controle","Egels vermijden compost volledig","Het is enkel nodig in de winter"]'::jsonb,
 '["Les hérissons utilisent souvent les tas de compost comme abri ou nid","Le compost est toujours sûr sans vérification","Les hérissons évitent totalement le compost","Ce n''est nécessaire qu''en hiver"]'::jsonb,
 '["Hedgehogs often use compost heaps as shelter or a nest","Compost is always safe without checking","Hedgehogs completely avoid compost","It is only necessary in winter"]'::jsonb,
 0,'Composthopen zijn warm en beschut, perfecte plekken voor egels om te schuilen of te overwinteren.','Les tas de compost sont chauds et abrités, des endroits parfaits pour les hérissons pour s''abriter ou hiverner.','Compost heaps are warm and sheltered, perfect spots for hedgehogs to shelter or hibernate.'),
(2,'tekst','Wat moet je doen bij een vermoedelijk bouwafval of tuinvuur?','Que faut-il faire avant un feu de jardin ou débris de construction ?','What should you do before a garden bonfire or building debris pile?',
 '["De hoop verplaatsen of controleren op egels vlak voor het aansteken","Meteen aansteken zonder controle","Egels zoeken die plekken nooit op","Wachten tot de zomer"]'::jsonb,
 '["Déplacer ou vérifier le tas pour des hérissons juste avant l''allumage","L''allumer immédiatement sans vérifier","Les hérissons ne recherchent jamais ces endroits","Attendre l''été"]'::jsonb,
 '["Move the pile or check for hedgehogs right before lighting it","Light it immediately without checking","Hedgehogs never seek out such spots","Wait until summer"]'::jsonb,
 0,'Takkenhopen bedoeld voor een vreugdevuur zijn aantrekkelijke schuilplekken en moeten altijd gecontroleerd worden.','Les tas de branches destinés à un feu de joie sont des abris attractifs et doivent toujours être vérifiés.','Brush piles meant for a bonfire are attractive shelters and should always be checked.'),
(2,'tekst','Hoe herken je een egel die dringend hulp nodig heeft?','Comment reconnaître un hérisson qui a besoin d''aide urgente ?','How do you recognise a hedgehog urgently needing help?',
 '["Overdag actief buiten, wankelend of erg licht van gewicht","Rustig slapend in een nest overdag","Normaal foeragerend in de schemering","Opgerold in een bladerhoop ''s nachts"]'::jsonb,
 '["Actif dehors en plein jour, chancelant ou très léger","Endormi paisiblement dans un nid en journée","Fourrageant normalement au crépuscule","Roulé en boule dans un tas de feuilles la nuit"]'::jsonb,
 '["Active outside during daytime, wobbly or very underweight","Sleeping calmly in a nest during the day","Foraging normally at dusk","Curled up in a leaf pile at night"]'::jsonb,
 0,'Egels zijn nachtdieren; een egel die overdag rondloopt, wankelt of te licht is, heeft vaak hulp nodig.','Les hérissons sont nocturnes ; un hérisson actif en journée, chancelant ou trop léger a souvent besoin d''aide.','Hedgehogs are nocturnal; one active by day, wobbling or too light often needs help.'),
(3,'tekst','Wanneer beginnen egels doorgaans aan hun winterslaap?','Quand les hérissons commencent-ils généralement leur hibernation ?','When do hedgehogs typically begin hibernation?',
 '["Vanaf de late herfst wanneer temperaturen dalen","In het midden van de zomer","Ze houden nooit winterslaap","Enkel in januari"]'::jsonb,
 '["Fin d''automne quand les températures baissent","En plein été","Ils n''hibernent jamais","Uniquement en janvier"]'::jsonb,
 '["From late autumn as temperatures drop","In the middle of summer","They never hibernate","Only in January"]'::jsonb,
 0,'Egels bouwen een winternest, een hibernaculum, en verlagen hun lichaamstemperatuur sterk tijdens de winterslaap.','Les hérissons construisent un nid d''hiver, un hibernaculum, et abaissent fortement leur température corporelle durant l''hibernation.','Hedgehogs build a winter nest, a hibernaculum, and greatly lower their body temperature during hibernation.'),
(3,'tekst','Waarom is het gevaarlijk om een winternest te storen?','Pourquoi est-il dangereux de déranger un nid d''hiver ?','Why is it dangerous to disturb a winter nest?',
 '["Wakker maken kost de egel veel dierbare energiereserves","Egels merken het nooit","Het is juist goed voor hen om wakker te worden","Winternesten bevatten nooit egels"]'::jsonb,
 '["Le réveiller coûte au hérisson de précieuses réserves d''énergie","Les hérissons ne remarquent jamais rien","C''est en fait bon pour eux d''être réveillés","Les nids d''hiver ne contiennent jamais de hérissons"]'::jsonb,
 '["Waking it costs the hedgehog precious energy reserves","Hedgehogs never notice anything","It is actually good for them to wake up","Winter nests never contain hedgehogs"]'::jsonb,
 0,'Elke keer dat een egel wakker wordt tijdens de winterslaap, verbruikt het kostbare vetreserves die nodig zijn om de winter te overleven.','Chaque réveil pendant l''hibernation consomme de précieuses réserves de graisse nécessaires pour survivre à l''hiver.','Each time a hedgehog wakes during hibernation it burns precious fat reserves needed to survive winter.'),
(3,'tekst','Wat is de beste periode om een tuin op te ruimen met egels in het achterhoofd?','Quelle est la meilleure période pour ranger un jardin en pensant aux hérissons ?','What is the best time to tidy a garden with hedgehogs in mind?',
 '["Laat op de dag begin herfst, of pas laat in het voorjaar","Midden in de winter","Enkel ''s nachts","Op willekeurig gelijk welk moment"]'::jsonb,
 '["Tard en début d''automne, ou tard au printemps","En plein hiver","Uniquement la nuit","À n''importe quel moment au hasard"]'::jsonb,
 '["Late in early autumn, or late in spring","In the middle of winter","Only at night","At any random moment"]'::jsonb,
 0,'Tuinieren buiten de winterslaap-periode vermindert het risico om slapende egels te storen of te verwonden.','Jardiner en dehors de la période d''hibernation réduit le risque de déranger ou blesser des hérissons endormis.','Gardening outside the hibernation period reduces the risk of disturbing or injuring sleeping hedgehogs.'),
(3,'tekst','Wat kan je doen om egels te helpen tijdens de winterslaap?','Que peut-on faire pour aider les hérissons pendant l''hibernation ?','What can you do to help hedgehogs during hibernation?',
 '["Een rustig hoekje met bladeren onaangeroerd laten in de tuin","Alle bladeren wegvegen voor een net gazon","Het nest verwarmen met een lamp","Het nest verplaatsen naar binnen"]'::jsonb,
 '["Laisser un coin tranquille avec des feuilles intact dans le jardin","Balayer toutes les feuilles pour une pelouse nette","Chauffer le nid avec une lampe","Déplacer le nid à l''intérieur"]'::jsonb,
 '["Leave a quiet corner with leaves undisturbed in the garden","Sweep away all leaves for a tidy lawn","Warm the nest with a lamp","Move the nest indoors"]'::jsonb,
 0,'Een ongestoord hoekje met bladeren en takken biedt egels een veilige, natuurlijke overwinteringsplek.','Un coin tranquille avec feuilles et branches offre aux hérissons un lieu d''hivernage sûr et naturel.','An undisturbed corner with leaves and branches gives hedgehogs a safe, natural place to overwinter.'),
(3,'tekst','Waarom verliezen sommige egels te veel gewicht voor de winterslaap?','Pourquoi certains hérissons perdent-ils trop de poids avant l''hibernation ?','Why do some hedgehogs lose too much weight before hibernation?',
 '["Onvoldoende voedsel in de late herfst door versnippering van leefgebied","Ze eten juist te veel in de herfst","Winterslaap heeft niets met gewicht te maken","Egels eten nooit in de herfst"]'::jsonb,
 '["Manque de nourriture en fin d''automne dû à la fragmentation de l''habitat","Ils mangent en fait trop en automne","L''hibernation n''a rien à voir avec le poids","Les hérissons ne mangent jamais en automne"]'::jsonb,
 '["Insufficient food in late autumn due to habitat fragmentation","They actually eat too much in autumn","Hibernation has nothing to do with weight","Hedgehogs never eat in autumn"]'::jsonb,
 0,'Een egel moet minstens 450-600 gram wegen om de winterslaap veilig te overleven.','Un hérisson doit peser au moins 450 à 600 grammes pour survivre en toute sécurité à l''hibernation.','A hedgehog needs to weigh at least 450-600 grams to safely survive hibernation.')
) AS v(module,vraag_type,nl,fr,en,onl,ofr,oen,ci,wnl,wfr,wen);

-- Vleermuis
WITH a AS (
  INSERT INTO public.academies (diersoort_naam, diersoort_naam_fr, diersoort_naam_en, slug, badge_icon, vragen_per_test, slaag_grens, beschrijving, beschrijving_fr, beschrijving_en, categorie, prioriteit)
  VALUES ('Vleermuis','Chauve-souris','Bat','vleermuis','vleermuis',15,12,'Ontdek hoe vleermuizen jagen met echolocatie, muggen bestrijden, beschermd zijn en hoe je hen helpt met kasten en minder licht.','Découvrez comment les chauves-souris chassent grâce à l''écholocation, luttent contre les moustiques, sont protégées et comment les aider avec des gîtes et moins de lumière.','Discover how bats hunt using echolocation, control mosquitoes, are protected by law, and how you can help with bat boxes and less light.','stadsnatuur',50)
  RETURNING id
)
INSERT INTO public.academy_vragen (academy_id, module, vraag_type, vraag_tekst, vraag_tekst_fr, vraag_tekst_en, opties, opties_fr, opties_en, correcte_optie_index, wist_je_dat, wist_je_dat_fr, wist_je_dat_en)
SELECT a.id, v.module, v.vraag_type, v.nl, v.fr, v.en, v.onl, v.ofr, v.oen, v.ci, v.wnl, v.wfr, v.wen
FROM a, (VALUES
(1,'tekst','Wat is echolocatie bij vleermuizen?','Qu''est-ce que l''écholocation chez les chauves-souris ?','What is echolocation in bats?',
 '["Het uitzenden van ultrasone geluiden en luisteren naar de echo om te navigeren","Het zien in het volledige donker zonder geluid","Een manier om te communiceren met vogels","Het ruiken van prooi op grote afstand"]'::jsonb,
 '["Émettre des sons ultrasoniques et écouter l''écho pour naviguer","Voir dans l''obscurité totale sans aucun son","Une façon de communiquer avec les oiseaux","Sentir une proie à grande distance"]'::jsonb,
 '["Emitting ultrasonic sounds and listening to the echo to navigate","Seeing in total darkness without any sound","A way to communicate with birds","Smelling prey from a great distance"]'::jsonb,
 0,'Vleermuizen zenden tot wel 200 ultrasone roepjes per seconde uit om prooien en obstakels te lokaliseren.','Les chauves-souris émettent jusqu''à 200 cris ultrasoniques par seconde pour localiser proies et obstacles.','Bats emit up to 200 ultrasonic calls per second to locate prey and obstacles.'),
(1,'tekst','Waarom zijn vleermuizen nuttig in de stad?','Pourquoi les chauves-souris sont-elles utiles en ville ?','Why are bats useful in the city?',
 '["Ze eten grote hoeveelheden muggen en andere insecten","Ze bestuiven bloemen zoals bijen","Ze eten enkel fruit uit tuinen","Ze jagen op kleine zoogdieren"]'::jsonb,
 '["Elles mangent de grandes quantités de moustiques et d''autres insectes","Elles pollinisent les fleurs comme les abeilles","Elles ne mangent que des fruits de jardin","Elles chassent de petits mammifères"]'::jsonb,
 '["They eat large amounts of mosquitoes and other insects","They pollinate flowers like bees","They only eat fruit from gardens","They hunt small mammals"]'::jsonb,
 0,'Een enkele vleermuis kan honderden muggen en insecten per nacht opeten, een natuurlijke plaagbestrijding.','Une seule chauve-souris peut manger des centaines de moustiques et insectes par nuit, une lutte antiparasitaire naturelle.','A single bat can eat hundreds of mosquitoes and insects per night, natural pest control.'),
(1,'tekst','Wat is de wettelijke status van vleermuizen in België?','Quel est le statut légal des chauves-souris en Belgique ?','What is the legal status of bats in Belgium?',
 '["Alle soorten zijn strikt beschermd, ook hun verblijfplaatsen","Ze mogen vrij bejaagd worden","Enkel zeldzame soorten zijn beschermd","Er bestaat geen enkele bescherming"]'::jsonb,
 '["Toutes les espèces sont strictement protégées, y compris leurs gîtes","Elles peuvent être chassées librement","Seules les espèces rares sont protégées","Il n''existe aucune protection"]'::jsonb,
 '["All species are strictly protected, including their roosts","They may be freely hunted","Only rare species are protected","There is no protection at all"]'::jsonb,
 0,'Alle vleermuissoorten en hun verblijfplaatsen zijn wettelijk beschermd, verstoring is verboden.','Toutes les espèces de chauves-souris et leurs gîtes sont légalement protégés, les déranger est interdit.','All bat species and their roosts are legally protected; disturbing them is prohibited.'),
(1,'tekst','Waarom mag je een vleermuisverblijf niet zomaar verwijderen uit een gebouw?','Pourquoi ne peut-on pas simplement retirer un gîte de chauves-souris d''un bâtiment ?','Why can you not simply remove a bat roost from a building?',
 '["Dit is wettelijk verboden zonder vergunning, ook buiten het broedseizoen","Vleermuizen hebben geen vaste verblijfplaats nodig","Het mag altijd zonder toestemming","Vleermuizen zijn niet beschermd in gebouwen"]'::jsonb,
 '["C''est interdit par la loi sans autorisation, même hors saison de reproduction","Les chauves-souris n''ont pas besoin de gîte fixe","C''est toujours permis sans autorisation","Les chauves-souris ne sont pas protégées dans les bâtiments"]'::jsonb,
 '["This is legally prohibited without a permit, even outside breeding season","Bats do not need a fixed roost","It is always allowed without permission","Bats are not protected inside buildings"]'::jsonb,
 0,'Vleermuizen keren jaar na jaar terug naar dezelfde verblijfplaats, verstoring kan hele kolonies schaden.','Les chauves-souris reviennent chaque année au même gîte, le déranger peut nuire à toute une colonie.','Bats return to the same roost year after year, disturbing it can harm entire colonies.'),
(1,'tekst','Wat eten de meeste vleermuissoorten in onze streken?','Que mangent la plupart des espèces de chauves-souris de nos régions ?','What do most bat species in our regions eat?',
 '["Insecten zoals muggen, motten en kevers","Enkel fruit en noten","Kleine vissen","Zaden en granen"]'::jsonb,
 '["Des insectes comme moustiques, papillons de nuit et coléoptères","Uniquement des fruits et des noix","De petits poissons","Des graines et céréales"]'::jsonb,
 '["Insects such as mosquitoes, moths and beetles","Only fruit and nuts","Small fish","Seeds and grains"]'::jsonb,
 0,'De meeste Europese vleermuizen zijn insecteneters en spelen een belangrijke rol in natuurlijke plaagbestrijding.','La plupart des chauves-souris européennes sont insectivores et jouent un rôle important dans la lutte antiparasitaire naturelle.','Most European bats are insectivorous and play an important role in natural pest control.'),
(2,'tekst','Wat is het doel van een vleermuiskast?','Quel est le but d''un gîte artificiel pour chauves-souris ?','What is the purpose of a bat box?',
 '["Een veilige, kunstmatige schuilplaats bieden voor rust en voortplanting","Vleermuizen wegjagen uit de tuin","Een voederplek maken voor vogels","Enkel decoratief, zonder functie"]'::jsonb,
 '["Offrir un abri artificiel sûr pour le repos et la reproduction","Chasser les chauves-souris du jardin","Créer un poste d''alimentation pour oiseaux","Uniquement décoratif, sans fonction"]'::jsonb,
 '["To provide a safe artificial shelter for resting and breeding","To scare bats away from the garden","To create a feeding spot for birds","Purely decorative, with no function"]'::jsonb,
 0,'Vleermuiskasten compenseren het verlies van natuurlijke verblijfplaatsen zoals holle bomen en oude gebouwen.','Les gîtes artificiels compensent la perte d''abris naturels comme les arbres creux et les vieux bâtiments.','Bat boxes compensate for the loss of natural roosts like hollow trees and old buildings.'),
(2,'tekst','Op welke hoogte hang je een vleermuiskast het best op?','À quelle hauteur faut-il idéalement accrocher un gîte à chauves-souris ?','At what height should you best hang a bat box?',
 '["Minstens 3 tot 4 meter hoog, uit bereik van katten","Op ooghoogte, ongeveer 1 meter","Vlak boven de grond","Hoogte maakt geen enkel verschil"]'::jsonb,
 '["Au moins 3 à 4 mètres de haut, hors de portée des chats","À hauteur des yeux, environ 1 mètre","Juste au-dessus du sol","La hauteur ne fait aucune différence"]'::jsonb,
 '["At least 3 to 4 metres high, out of reach of cats","At eye level, about 1 metre","Just above the ground","Height makes no difference at all"]'::jsonb,
 0,'Een hoge, veilige positie beschermt vleermuizen tegen roofdieren zoals katten en verstoring.','Une position haute et sûre protège les chauves-souris des prédateurs comme les chats et des perturbations.','A high, safe position protects bats from predators like cats and disturbance.'),
(2,'tekst','Waarom is lichtvervuiling een probleem voor vleermuizen?','Pourquoi la pollution lumineuse est-elle un problème pour les chauves-souris ?','Why is light pollution a problem for bats?',
 '["Fel licht verstoort hun jachtgedrag en vliegroutes","Vleermuizen houden juist van fel licht","Licht heeft geen enkel effect op vleermuizen","Het maakt insecten makkelijker te vinden voor vleermuizen"]'::jsonb,
 '["Une lumière vive perturbe leur comportement de chasse et leurs trajectoires de vol","Les chauves-souris aiment justement la lumière vive","La lumière n''a aucun effet sur les chauves-souris","Cela facilite la recherche d''insectes pour les chauves-souris"]'::jsonb,
 '["Bright light disrupts their hunting behaviour and flight routes","Bats actually like bright light","Light has no effect on bats at all","It makes it easier for bats to find insects"]'::jsonb,
 0,'Veel vleermuissoorten mijden verlichte gebieden, waardoor kunstlicht hun jachtgebied en vliegroutes versnippert.','Beaucoup d''espèces de chauves-souris évitent les zones éclairées, la lumière artificielle fragmente donc leur territoire de chasse.','Many bat species avoid lit areas, so artificial light fragments their hunting territory and flight routes.'),
(2,'tekst','Wat kan je doen om je tuin vleermuisvriendelijker te maken?','Que peut-on faire pour rendre un jardin plus favorable aux chauves-souris ?','What can you do to make your garden more bat-friendly?',
 '["Nachtbloeiende planten aanplanten die insecten aantrekken","Alle verlichting de hele nacht laten branden","Een vijver volledig afdekken met netten","Alle bomen en struiken verwijderen"]'::jsonb,
 '["Planter des fleurs à floraison nocturne qui attirent les insectes","Laisser tous les éclairages allumés toute la nuit","Couvrir entièrement un bassin avec des filets","Enlever tous les arbres et arbustes"]'::jsonb,
 '["Plant night-blooming flowers that attract insects","Leave all lights on all night","Cover a pond entirely with nets","Remove all trees and shrubs"]'::jsonb,
 0,'Nachtbloeiende planten trekken nachtvlinders en andere insecten aan, wat een goede voedselbron is voor vleermuizen.','Les fleurs à floraison nocturne attirent papillons de nuit et autres insectes, une bonne source de nourriture pour les chauves-souris.','Night-blooming plants attract moths and other insects, which are a good food source for bats.'),
(2,'tekst','Waarom is een vijver of waterpartij aantrekkelijk voor vleermuizen?','Pourquoi un bassin ou un point d''eau est-il attractif pour les chauves-souris ?','Why is a pond or water feature attractive to bats?',
 '["Er verzamelen zich veel insecten boven water om te drinken en te jagen","Vleermuizen drinken enkel regenwater van bladeren","Water heeft geen enkele aantrekkingskracht","Vleermuizen zwemmen graag in vijvers"]'::jsonb,
 '["Beaucoup d''insectes s''y rassemblent pour boire et chasser","Les chauves-souris ne boivent que l''eau de pluie sur les feuilles","L''eau n''a aucun attrait","Les chauves-souris aiment nager dans les bassins"]'::jsonb,
 '["Many insects gather there to drink and hunt, attracting bats","Bats only drink rainwater from leaves","Water has no attraction at all","Bats like to swim in ponds"]'::jsonb,
 0,'Vleermuizen jagen vaak laag over water waar insecten zich verzamelen, en drinken er ook tijdens de vlucht.','Les chauves-souris chassent souvent bas au-dessus de l''eau où les insectes se rassemblent, et y boivent aussi en vol.','Bats often hunt low over water where insects gather, and drink there while flying.'),
(3,'tekst','Wat moet je doen als je een vleermuiskolonie vindt in je zolder?','Que faire si l''on trouve une colonie de chauves-souris dans son grenier ?','What should you do if you find a bat colony in your attic?',
 '["Contact opnemen met een vleermuiswerkgroep voordat je iets onderneemt","Meteen alle openingen dichtmaken","De vleermuizen zelf verjagen met rook","Niets doen is verboden, je moet ze meteen verwijderen"]'::jsonb,
 '["Contacter un groupe de protection des chauves-souris avant d''agir","Boucher immédiatement toutes les ouvertures","Chasser soi-même les chauves-souris avec de la fumée","Ne rien faire est interdit, il faut les retirer immédiatement"]'::jsonb,
 '["Contact a bat conservation group before doing anything","Immediately seal all openings","Chase the bats away yourself with smoke","Doing nothing is illegal, you must remove them immediately"]'::jsonb,
 0,'Omdat vleermuizen wettelijk beschermd zijn, mag je een kolonie niet zomaar verstoren of verwijderen.','Comme les chauves-souris sont légalement protégées, on ne peut pas simplement déranger ou retirer une colonie.','Because bats are legally protected, you may not simply disturb or remove a colony.'),
(3,'tekst','Wanneer is het risico op verstoring van een vleermuiskolonie het grootst?','Quand le risque de perturber une colonie de chauves-souris est-il le plus élevé ?','When is the risk of disturbing a bat colony highest?',
 '["Tijdens de kraamperiode in de zomer en tijdens de winterslaap","In de late herfst voor de winterslaap begint","Vleermuizen kunnen nooit verstoord worden","Enkel overdag in de winter"]'::jsonb,
 '["Pendant la période de mise bas en été et pendant l''hibernation","Fin d''automne avant le début de l''hibernation","Les chauves-souris ne peuvent jamais être dérangées","Uniquement le jour en hiver"]'::jsonb,
 '["During the maternity period in summer and during hibernation","In late autumn before hibernation begins","Bats can never be disturbed","Only during the day in winter"]'::jsonb,
 0,'Verstoring tijdens de kraamperiode kan jongen doden, en verstoring tijdens winterslaap verbruikt vitale energiereserves.','Une perturbation en période de mise bas peut tuer les jeunes, et pendant l''hibernation elle épuise des réserves d''énergie vitales.','Disturbance during the maternity period can kill young, and disturbance during hibernation drains vital energy reserves.'),
(3,'tekst','Hoe herken je een vleermuis die hulp nodig heeft overdag op de grond?','Comment reconnaître une chauve-souris ayant besoin d''aide, trouvée au sol en journée ?','How do you recognise a bat needing help found on the ground during the day?',
 '["Ze kan niet wegvliegen, lijkt zwak of verzwakt","Ze hangt rustig ondersteboven in een boom","Ze jaagt actief boven het water","Ze vliegt hoog in de lucht rond"]'::jsonb,
 '["Elle ne peut pas s''envoler, semble faible ou affaiblie","Elle est suspendue tranquillement la tête en bas dans un arbre","Elle chasse activement au-dessus de l''eau","Elle vole haut dans les airs"]'::jsonb,
 '["It cannot fly away, appears weak or exhausted","It hangs calmly upside down in a tree","It is actively hunting above the water","It is flying high in the sky"]'::jsonb,
 0,'Een vleermuis op de grond overdag die niet kan wegvliegen, heeft mogelijk hulp nodig van een opvangcentrum.','Une chauve-souris au sol en journée incapable de s''envoler a peut-être besoin de l''aide d''un centre de soins.','A bat on the ground during the day that cannot fly away may need help from a rescue centre.'),
(3,'tekst','Hoe pak je een gevonden vleermuis best op als hulp nodig lijkt?','Comment manipuler une chauve-souris trouvée qui semble avoir besoin d''aide ?','How should you handle a found bat that seems to need help?',
 '["Met handschoenen aan, voorzichtig in een geventileerd doosje","Met blote handen stevig vastgrijpen","Nooit aanraken, ook niet met handschoenen","Vasthouden aan de vleugels om te dragen"]'::jsonb,
 '["Avec des gants, délicatement dans une boîte ventilée","À mains nues, en la saisissant fermement","Ne jamais toucher, même avec des gants","La tenir par les ailes pour la transporter"]'::jsonb,
 '["Wearing gloves, gently placed in a ventilated box","Grip it firmly with bare hands","Never touch it, even with gloves","Hold it by the wings to carry it"]'::jsonb,
 0,'Handschoenen beschermen zowel jou tegen een mogelijke beet als de vleermuis tegen stress door direct huidcontact.','Les gants protègent à la fois contre une éventuelle morsure et la chauve-souris du stress lié au contact direct.','Gloves protect you from a possible bite and the bat from stress caused by direct skin contact.'),
(3,'tekst','Waarom mag je nooit zomaar een boom met holtes vellen zonder controle?','Pourquoi ne faut-il jamais abattre un arbre à cavités sans vérification ?','Why should you never fell a tree with cavities without checking first?',
 '["Boomholtes zijn vaak verblijfplaatsen van beschermde vleermuizen","Bomen met holtes zijn altijd dood en waardeloos","Vleermuizen wonen nooit in bomen","Het is enkel een esthetische kwestie"]'::jsonb,
 '["Les cavités des arbres sont souvent des gîtes de chauves-souris protégées","Les arbres à cavités sont toujours morts et sans valeur","Les chauves-souris ne vivent jamais dans les arbres","C''est uniquement une question esthétique"]'::jsonb,
 '["Tree cavities are often roosts for protected bats","Trees with cavities are always dead and worthless","Bats never live in trees","It is purely an aesthetic matter"]'::jsonb,
 0,'Holle bomen zijn belangrijke natuurlijke schuilplaatsen; een ecologische controle voorkomt onbedoelde schade aan kolonies.','Les arbres creux sont d''importants abris naturels ; un contrôle écologique évite de nuire par inadvertance aux colonies.','Hollow trees are important natural roosts; an ecological check prevents accidental harm to colonies.')
) AS v(module,vraag_type,nl,fr,en,onl,ofr,oen,ci,wnl,wfr,wen);

-- Eekhoorn
WITH a AS (
  INSERT INTO public.academies (diersoort_naam, diersoort_naam_fr, diersoort_naam_en, slug, badge_icon, vragen_per_test, slaag_grens, beschrijving, beschrijving_fr, beschrijving_en, categorie, prioriteit)
  VALUES ('Eekhoorn','Écureuil','Squirrel','eekhoorn','eekhoorn',15,12,'Leer over wintervoorraden van eekhoorns, hun nesten in bomen, het belang van parkbomen en veilig voeren zonder brood of gezouten pinda''s.','Découvrez les réserves d''hiver des écureuils, leurs nids dans les arbres, l''importance des arbres du parc et comment les nourrir sans pain ni cacahuètes salées.','Learn about squirrels'' winter food stores, their tree nests, the importance of park trees, and safe feeding without bread or salted peanuts.','stadsnatuur',50)
  RETURNING id
)
INSERT INTO public.academy_vragen (academy_id, module, vraag_type, vraag_tekst, vraag_tekst_fr, vraag_tekst_en, opties, opties_fr, opties_en, correcte_optie_index, wist_je_dat, wist_je_dat_fr, wist_je_dat_en)
SELECT a.id, v.module, v.vraag_type, v.nl, v.fr, v.en, v.onl, v.ofr, v.oen, v.ci, v.wnl, v.wfr, v.wen
FROM a, (VALUES
(1,'tekst','Wat doen eekhoorns met noten en zaden in de herfst?','Que font les écureuils avec les noix et graines en automne ?','What do squirrels do with nuts and seeds in autumn?',
 '["Ze verstoppen ze verspreid op verschillende plekken als wintervoorraad","Ze eten alles meteen op","Ze verkopen ze niet, ze geven ze weg aan vogels","Ze laten ze gewoon liggen"]'::jsonb,
 '["Ils les cachent dispersés à différents endroits comme réserve d''hiver","Ils mangent tout immédiatement","Ils les donnent aux oiseaux","Ils les laissent simplement au sol"]'::jsonb,
 '["They hide them scattered in different spots as a winter store","They eat everything immediately","They give them away to birds","They just leave them lying around"]'::jsonb,
 0,'Eekhoorns verstoppen honderden voorraadjes verspreid over hun territorium, een techniek genaamd scatter hoarding.','Les écureuils cachent des centaines de petites réserves dispersées sur leur territoire, une technique appelée dissémination des réserves.','Squirrels hide hundreds of small caches scattered across their territory, a technique called scatter hoarding.'),
(1,'tekst','Hoe vinden eekhoorns hun verstopte voorraden terug?','Comment les écureuils retrouvent-ils leurs réserves cachées ?','How do squirrels find their hidden food stores again?',
 '["Vooral met hun reukvermogen en gedeeltelijk geheugen","Ze vinden nooit iets terug","Ze gebruiken enkel hun ogen","Ze volgen sporen van andere dieren"]'::jsonb,
 '["Surtout grâce à leur odorat et en partie leur mémoire","Ils ne retrouvent jamais rien","Ils utilisent uniquement leurs yeux","Ils suivent les traces d''autres animaux"]'::jsonb,
 '["Mainly using their sense of smell and partly memory","They never find anything again","They use only their eyes","They follow tracks of other animals"]'::jsonb,
 0,'Eekhoorns ruiken voorraden zelfs onder een laag sneeuw, maar vergeten ook veel plekken, wat helpt bij het verspreiden van boomzaden.','Les écureuils flairent leurs réserves même sous la neige, mais en oublient beaucoup, ce qui aide à disperser les graines d''arbres.','Squirrels can smell caches even under snow, but also forget many spots, which helps spread tree seeds.'),
(1,'tekst','Wat is een eekhoornnest, ook wel een drey genoemd?','Qu''est-ce qu''un nid d''écureuil, aussi appelé "drey" ?','What is a squirrel nest, also called a drey?',
 '["Een bolvormig nest van takken en bladeren hoog in een boom","Een hol diep onder de grond","Een nest gemaakt van modder","Eekhoorns bouwen nooit nesten"]'::jsonb,
 '["Un nid sphérique de branches et de feuilles haut dans un arbre","Un terrier profond sous terre","Un nid fait de boue","Les écureuils ne construisent jamais de nid"]'::jsonb,
 '["A ball-shaped nest of twigs and leaves high in a tree","A burrow deep underground","A nest made of mud","Squirrels never build nests"]'::jsonb,
 0,'Een drey is een bolvormig nest gemaakt van takken, met een zachte binnenbekleding van mos en bladeren.','Un "drey" est un nid sphérique fait de branches, avec un intérieur doux tapissé de mousse et de feuilles.','A drey is a ball-shaped nest made of twigs, with a soft lining of moss and leaves inside.'),
(1,'tekst','Hoe onderscheid je een eekhoornnest van een kraaiennest?','Comment distinguer un nid d''écureuil d''un nid de corneille ?','How do you tell a squirrel nest apart from a crow''s nest?',
 '["Een eekhoornnest is dichter en bolvormig, een kraaiennest is opener en platter","Ze zijn altijd identiek en niet te onderscheiden","Kraaiennesten zijn altijd op de grond","Eekhoornnesten hebben altijd een dak van bladeren van plastic"]'::jsonb,
 '["Le nid d''écureuil est dense et sphérique, celui de la corneille plus ouvert et plat","Ils sont toujours identiques et impossibles à distinguer","Les nids de corneille sont toujours au sol","Les nids d''écureuil ont toujours un toit en plastique"]'::jsonb,
 '["A squirrel nest is denser and round, a crow''s nest is more open and flatter","They are always identical and indistinguishable","Crow nests are always on the ground","Squirrel nests always have a plastic roof"]'::jsonb,
 0,'Eekhoornnesten zijn compacter en dichter dan de open, platte nesten van kraaien, vaak tegen de stam aan.','Les nids d''écureuils sont plus compacts et denses que les nids ouverts et plats des corneilles, souvent contre le tronc.','Squirrel nests are more compact and denser than crows'' open, flat nests, often built against the trunk.'),
(1,'tekst','Waarom bouwen eekhoorns soms meerdere nesten?','Pourquoi les écureuils construisent-ils parfois plusieurs nids ?','Why do squirrels sometimes build multiple nests?',
 '["Als reservenest en om parasieten te ontlopen","Ze bouwen altijd maar één enkel nest per leven","Om andere dieren te verjagen","Enkel voor de decoratie van het territorium"]'::jsonb,
 '["Comme nid de secours et pour échapper aux parasites","Ils ne construisent toujours qu''un seul nid dans leur vie","Pour chasser d''autres animaux","Uniquement pour décorer leur territoire"]'::jsonb,
 '["As a backup nest and to escape parasites","They only ever build a single nest in their life","To chase away other animals","Purely to decorate their territory"]'::jsonb,
 0,'Meerdere nesten geven eekhoorns een vluchtplek bij gevaar en helpen parasietenbesmetting te beperken.','Plusieurs nids offrent aux écureuils un abri en cas de danger et limitent l''infestation par les parasites.','Multiple nests give squirrels an escape option in case of danger and help limit parasite infestation.'),
(2,'tekst','Waarom zijn oude, grote bomen belangrijk voor eekhoorns in een park?','Pourquoi les vieux grands arbres sont-ils importants pour les écureuils dans un parc ?','Why are old, large trees important for squirrels in a park?',
 '["Ze bieden holtes, nestplekken en veel voedsel zoals noten","Oude bomen zijn nutteloos voor dieren","Enkel jonge bomen zijn geschikt","Eekhoorns gebruiken enkel struiken"]'::jsonb,
 '["Ils offrent des cavités, des sites de nidification et beaucoup de nourriture comme des noix","Les vieux arbres sont inutiles pour les animaux","Seuls les jeunes arbres conviennent","Les écureuils n''utilisent que des buissons"]'::jsonb,
 '["They offer cavities, nesting spots and plenty of food like nuts","Old trees are useless to animals","Only young trees are suitable","Squirrels only use shrubs"]'::jsonb,
 0,'Oude bomen hebben vaak holtes die dienst doen als schuilplaats en produceren meer zaden en noten.','Les vieux arbres ont souvent des cavités servant d''abri et produisent plus de graines et de noix.','Old trees often have cavities that serve as shelter and produce more seeds and nuts.'),
(2,'tekst','Welke boomsoorten zijn bijzonder waardevol als voedselbron voor eekhoorns?','Quelles essences d''arbres sont particulièrement précieuses comme source de nourriture pour les écureuils ?','Which tree species are particularly valuable as a food source for squirrels?',
 '["Eik, hazelaar en beuk vanwege hun noten en eikels","Enkel naaldbomen zoals de spar","Bomen zonder vruchten of zaden","Enkel exotische, ingevoerde bomen"]'::jsonb,
 '["Chêne, noisetier et hêtre pour leurs noix et glands","Uniquement les conifères comme l''épicéa","Les arbres sans fruits ni graines","Uniquement les arbres exotiques importés"]'::jsonb,
 '["Oak, hazel and beech because of their acorns and nuts","Only conifers such as spruce","Trees without any fruit or seeds","Only exotic, imported trees"]'::jsonb,
 0,'Eikels, hazelnoten en beukennootjes zijn energierijke voedselbronnen die eekhoorns helpen de winter door te komen.','Glands, noisettes et faînes sont des sources d''énergie qui aident les écureuils à passer l''hiver.','Acorns, hazelnuts and beech nuts are energy-rich food sources that help squirrels survive winter.'),
(2,'tekst','Waarom is een aaneengesloten bomenrij belangrijk voor eekhoorns in de stad?','Pourquoi une rangée d''arbres continue est-elle importante pour les écureuils en ville ?','Why is a continuous row of trees important for squirrels in the city?',
 '["Het laat hen veilig van boom naar boom bewegen zonder de grond te moeten oversteken","Eekhoorns bewegen zich enkel over de grond","Ze hebben geen bomen nodig om zich te verplaatsen","Losse bomen zijn altijd beter dan een rij"]'::jsonb,
 '["Cela leur permet de se déplacer en sécurité d''arbre en arbre sans traverser le sol","Les écureuils ne se déplacent que sur le sol","Ils n''ont pas besoin d''arbres pour se déplacer","Des arbres isolés sont toujours préférables à une rangée"]'::jsonb,
 '["It lets them move safely from tree to tree without crossing the ground","Squirrels only move along the ground","They do not need trees to get around","Isolated trees are always better than a row"]'::jsonb,
 0,'Verbonden boomkruinen vormen groene snelwegen waarlangs eekhoorns veilig kunnen reizen, weg van verkeer en katten.','Les cimes d''arbres connectées forment des autoroutes vertes permettant aux écureuils de voyager en sécurité, loin de la circulation et des chats.','Connected tree canopies form green highways letting squirrels travel safely, away from traffic and cats.'),
(2,'tekst','Wat gebeurt er als teveel losstaande bomen in een park worden gekapt?','Que se passe-t-il si trop d''arbres isolés d''un parc sont abattus ?','What happens if too many isolated trees in a park are cut down?',
 '["Eekhoorns verliezen leefgebied en veilige verplaatsingsroutes","Er verandert niets voor eekhoorns","Eekhoorns verhuizen probleemloos naar de grond","Het is enkel een esthetisch verlies"]'::jsonb,
 '["Les écureuils perdent leur habitat et leurs routes de déplacement sûres","Rien ne change pour les écureuils","Les écureuils déménagent sans problème au sol","C''est uniquement une perte esthétique"]'::jsonb,
 '["Squirrels lose habitat and safe travel routes","Nothing changes for squirrels","Squirrels move to the ground without any issue","It is purely an aesthetic loss"]'::jsonb,
 0,'Het verlies van bomen fragmenteert het leefgebied van eekhoorns en verhoogt het risico op verkeersslachtoffers.','La perte d''arbres fragmente l''habitat des écureuils et augmente le risque d''accidents de la circulation.','The loss of trees fragments squirrel habitat and increases the risk of traffic casualties.'),
(2,'tekst','Waarom is dood hout in een park nuttig voor eekhoorns?','Pourquoi le bois mort dans un parc est-il utile aux écureuils ?','Why is dead wood in a park useful for squirrels?',
 '["Het trekt insecten aan en biedt vaak holtes om te schuilen","Dood hout is altijd gevaarlijk en nutteloos","Eekhoorns gebruiken enkel levende bomen","Het moet altijd meteen verwijderd worden"]'::jsonb,
 '["Cela attire les insectes et offre souvent des cavités pour s''abriter","Le bois mort est toujours dangereux et inutile","Les écureuils n''utilisent que des arbres vivants","Il doit toujours être retiré immédiatement"]'::jsonb,
 '["It attracts insects and often provides cavities for shelter","Dead wood is always dangerous and useless","Squirrels only use living trees","It must always be removed immediately"]'::jsonb,
 0,'Dode en verzwakte bomen ontwikkelen vaak holtes die ideaal zijn als schuilplaats of nestplek voor eekhoorns.','Les arbres morts ou affaiblis développent souvent des cavités idéales comme abri ou site de nidification pour les écureuils.','Dead or weakened trees often develop cavities ideal as shelter or nesting spots for squirrels.'),
(3,'tekst','Waarom mag je eekhoorns geen brood geven?','Pourquoi ne faut-il pas donner de pain aux écureuils ?','Why should you not give squirrels bread?',
 '["Brood heeft weinig voedingswaarde en kan spijsverteringsproblemen geven","Brood is het beste voedsel voor eekhoorns","Eekhoorns eten nooit iets van mensen","Brood maakt hun vacht mooier"]'::jsonb,
 '["Le pain a peu de valeur nutritive et peut causer des problèmes digestifs","Le pain est la meilleure nourriture pour les écureuils","Les écureuils ne mangent jamais rien venant des humains","Le pain rend leur pelage plus beau"]'::jsonb,
 '["Bread has little nutritional value and can cause digestive problems","Bread is the best food for squirrels","Squirrels never eat anything from humans","Bread makes their fur nicer"]'::jsonb,
 0,'Brood levert nauwelijks de vetten en eiwitten die eekhoorns nodig hebben en kan hun spijsvertering verstoren.','Le pain n''apporte presque pas les graisses et protéines nécessaires aux écureuils et peut perturber leur digestion.','Bread provides hardly any of the fats and proteins squirrels need and can upset their digestion.'),
(3,'tekst','Waarom zijn gezouten pinda''s slecht voor eekhoorns?','Pourquoi les cacahuètes salées sont-elles mauvaises pour les écureuils ?','Why are salted peanuts bad for squirrels?',
 '["Teveel zout is schadelijk voor hun nieren en gezondheid","Zout is juist gezond voor eekhoorns in kleine hoeveelheden","Pinda''s zijn altijd giftig voor eekhoorns","Gezouten pinda''s hebben geen enkel effect"]'::jsonb,
 '["Trop de sel est nocif pour leurs reins et leur santé","Le sel est en fait sain pour les écureuils en petite quantité","Les cacahuètes sont toujours toxiques pour les écureuils","Les cacahuètes salées n''ont aucun effet"]'::jsonb,
 '["Too much salt is harmful to their kidneys and health","Salt is actually healthy for squirrels in small amounts","Peanuts are always toxic to squirrels","Salted peanuts have no effect at all"]'::jsonb,
 0,'Overmatig zout kan bij kleine dieren zoals eekhoorns leiden tot uitdroging en nierproblemen.','Un excès de sel peut entraîner déshydratation et problèmes rénaux chez les petits animaux comme les écureuils.','Excess salt can lead to dehydration and kidney problems in small animals like squirrels.'),
(3,'tekst','Wat is een veilig alternatief om eekhoorns bij te voeren in de winter?','Quelle est une alternative sûre pour nourrir les écureuils en hiver ?','What is a safe alternative for feeding squirrels in winter?',
 '["Ongezouten noten zoals walnoten en hazelnoten in de schil","Chips en koekjes","Chocolade en snoep","Melkproducten zoals kaas"]'::jsonb,
 '["Des noix non salées comme des noix et noisettes en coque","Des chips et biscuits","Du chocolat et des bonbons","Des produits laitiers comme le fromage"]'::jsonb,
 '["Unsalted nuts like walnuts and hazelnuts in their shell","Crisps and biscuits","Chocolate and sweets","Dairy products like cheese"]'::jsonb,
